export const IRANIAN_FOOD_LICENSED_PRIMARY_COUNT = 24;
export const IRANIAN_FOOD_PLACEHOLDER_COUNT = 9;

export function getIranianFoodImage(
  item: Pick<FoodCatalogItem, 'nameFa' | 'category' | 'sourceType'>,
): IranianFoodImageEntry | null {
  if (item.sourceType === 'custom') return null;
  return LICENSED_PRIMARY_BY_NAME_FA[item.nameFa]
    ?? PLACEHOLDER_BY_CATEGORY[item.category]
    ?? null;
}
